@php
    $xgUser = auth()->user();
    $xgRole = $xgUser?->role ?? 'guest';
    $canInstructor = $xgUser ? $xgUser->hasRole('instructor') : false;
    $canAdmin = $xgUser ? $xgUser->hasRole('admin') : false;
    $xgInitials = $xgUser
        ? collect(explode(' ', trim($xgUser->name)))->filter()->take(2)->map(fn($w) => mb_strtoupper(mb_substr($w, 0, 1)))->implode('')
        : 'GU';
    $xgLatestEndedSession = null;
    try {
        $xgLab = \App\Models\Lab::query()->first();
        $xgActiveSession = $xgLab ? \App\Models\LabSession::activeFor($xgLab->id)?->load('profile') : null;
        $xgLatestEndedSession = $xgLab ? \App\Models\LabSession::query()->where('lab_id', $xgLab->id)->where('status', 'ended')->latest('ended_at')->first(['id']) : null;
        $xgTotalPcs = $xgLab ? \App\Models\Pc::query()->active()->where('lab_id', $xgLab->id)->count() : 0;
        $xgOnlinePcs = $xgLab ? \App\Models\Pc::query()->active()->where('lab_id', $xgLab->id)->get()->filter->online()->count() : 0;
        $xgTz = \App\Models\Setting::get('timezone') ?: config('app.timezone', 'UTC');
        $xgSigVer = \App\Models\SignatureVersion::active()?->version ?? 'Not published';
        $xgServerIp = $xgLab?->ccc_ip ?: (\App\Models\Setting::get('ccc_ip') ?: request()->getHost());
    } catch (\Throwable) {
        $xgLab = null;
        $xgActiveSession = null;
        $xgLatestEndedSession = null;
        $xgTotalPcs = 0;
        $xgOnlinePcs = 0;
        $xgTz = config('app.timezone', 'UTC');
        $xgSigVer = '—';
        $xgServerIp = request()->getHost();
    }
    $xgFlashStatus = session('status');
    $xgFlashErrors = isset($errors) && $errors->any() ? $errors->all() : [];
@endphp
