  <div class="overlay top" x-show="open" x-cloak x-transition.opacity @click.self="open = false">
    <div class="palette" role="dialog" aria-label="Command palette">
      <input x-ref="q" x-model="q" placeholder="Search pages, PCs and actions…" @input="idx = 0" @keydown.down.prevent="move(1)" @keydown.up.prevent="move(-1)" @keydown.enter.prevent="go(idx)">
      <ul>
        <template x-for="(it, i) in items" :key="it.g + it.t">
          <li :class="{on: i === idx}" @mouseenter="idx = i" @click="go(i)">
            <svg class="i"><use :href="'#i-' + it.icon"/></svg><span x-text="it.t"></span><span class="k" x-text="it.k || it.g"></span>
          </li>
        </template>
        <li x-show="!items.length" style="color:var(--muted)">No matches</li>
      </ul>
      <div class="foot"><span>↑↓ to move</span><span>Enter to open</span><span>Esc to close</span></div>
    </div>
  </div>
</div>

<div class="toasts" x-data aria-live="polite">
  <template x-for="t in $store.toasts.items" :key="t.id">
    <div class="toast" x-transition.opacity>
      <span class="dot" :class="t.severity"></span><span x-text="t.title"></span>
      <button @click="$store.toasts.remove(t.id)" aria-label="Dismiss">&times;</button>
    </div>
  </template>
</div>
</body>
</html>
